# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ALLAH\'IN (C.C.) GÜZEL İSİMLERİ: HÂDÎ, SELÂM VE VEKÎL</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">El-Hâdî (الْهَادِي)</text>\n  <text x="127" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">"Hidayet ve Doğru Yol Veren"</text>\n  <text x="40" y="132" font-size="11" fill="#334155">• Kullarını iyiliğe, doğruluğa ve</text>\n  <text x="45" y="148" font-size="11" fill="#334155">mutluluğa ulaştırandır.</text>\n  <text x="40" y="172" font-size="11" fill="#334155">• Fatiha Suresi: "Bizi dosdoğru</text>\n  <text x="45" y="188" font-size="11" fill="#334155">yola (sırât-ı müstakîm) ilet!"</text>\n  <text x="127" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Rehber: Kur\'an ve Sünnet</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Es-Selâm (السَّلَامُ)</text>\n  <text x="350" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">"Esenlik ve Barış Kaynağı"</text>\n  <text x="262" y="132" font-size="11" fill="#334155">• Her türlü eksiklikten uzak,</text>\n  <text x="267" y="148" font-size="11" fill="#334155">kullarını selamete çıkarandır.</text>\n  <text x="262" y="172" font-size="11" fill="#334155">• Namaz sonrası: "Allâhümme</text>\n  <text x="267" y="188" font-size="11" fill="#334155">entes-selâmü ve minkes-selâm"</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Yansıması: Selamlaşmak ve Barış</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#a16207">El-Vekîl (الْوَكِيلُ)</text>\n  <text x="572" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">"Güvenilen Koruyucu Dost"</text>\n  <text x="485" y="132" font-size="11" fill="#334155">• Kendisine sığınanların işlerini</text>\n  <text x="490" y="148" font-size="11" fill="#334155">en güzel şekilde yoluna koyandır.</text>\n  <text x="485" y="172" font-size="11" fill="#334155">• Zikir: "Hasbünallâhü ve</text>\n  <text x="490" y="188" font-size="11" fill="#334155">ni\'mel vekîl" (Allah bize yeter)</text>\n  <text x="572" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Yansıması: Tedbir ve Tevekkül</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EL-VEKÎL İSMİNİN HAYATIMIZA YANSIMASI: DUA VE TEVEKKÜL BİLİNCİ</text>\n  <rect x="40" y="55" width="280" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="180" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Adım: Çalışma ve Tedbir (Fiilî Dua)</text>\n  <text x="55" y="112" font-size="11.5" fill="#334155">• Öğrencinin dersine düzenli çalışması</text>\n  <text x="55" y="136" font-size="11.5" fill="#334155">• Çiftçinin tarlayı sürüp tohum ekmesi</text>\n  <text x="55" y="160" font-size="11.5" fill="#334155">• Hastanın doktora gidip ilaç kullanması</text>\n  <text x="55" y="184" font-size="11.5" fill="#334155">• Deveyi önce sağlam kazığa bağlamak</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Üzerimize düşen sorumluluğu tam yapmak!</text>\n  <rect x="360" y="55" width="300" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="510" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Adım: Dua ve Güven (Sözlü Dua)</text>\n  <text x="375" y="112" font-size="11.5" fill="#334155">• Sonucu El-Vekîl olan Allah\'tan beklemek</text>\n  <text x="375" y="136" font-size="11.5" fill="#334155">• Ümitsizliğe ve kaygıya kapılmamak</text>\n  <text x="375" y="160" font-size="11.5" fill="#334155">• "Allah bize yeter, O ne güzel vekildir!"</text>\n  <text x="385" y="178" font-size="11" fill="#475569">(Âl-i İmrân Suresi, 173. ayet) bilinciyle yaşamak</text>\n  <text x="510" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Gerçek Tevekkül = Tedbir + Dua + Teslimiyet</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE ÖZETİ: DİNİMİZ İSLAM VE MÜMİN KİMLİĞİ</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İslam\'ın Temel Özellikleri</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Tevhid Dinidir: Allah\'ın birliğine dayanır.</text>\n  <text x="55" y="130" font-size="11.5" fill="#334155">• Evrenseldir: Tüm insanlığa hitap eder.</text>\n  <text x="55" y="152" font-size="11.5" fill="#334155">• Fıtrat Dinidir: İnsan doğasına ve akla uygundur.</text>\n  <text x="55" y="174" font-size="11.5" fill="#334155">• Kolaylık ve Denge Dinidir: Güç yetirebilene</text>\n  <text x="65" y="192" font-size="11" fill="#475569">sorumluluk yükler, dünya ve ahireti dengeler.</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">İman – İbadet – Ahlak Bütünlüğü</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Mümin: Kalbiyle iman edip güven veren kişi</text>\n  <text x="380" y="132" font-size="11.5" fill="#334155">• "Müslüman, elinden ve dilinden diğer</text>\n  <text x="390" y="150" font-size="11" fill="#475569">insanların güvende olduğu kimsedir."</text>\n  <text x="380" y="176" font-size="11.5" fill="#334155">• İhsan: Allah\'ı görüyormuşçasına kulluk</text>\n  <text x="512" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Salih amel, imanı güzel ahlaka dönüştürür!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
